// src/crd.rs - RunStrategy enum and updated WorkspaceClaimSpec

use serde::{Deserialize, Serialize};
use strum::EnumString;

/// Run strategy for workspace lifecycle management.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, EnumString)]
#[serde(rename_all = "PascalCase")]
#[strum(serialize_all = "PascalCase")]
pub enum RunStrategy {
    /// Workspace runs continuously.
    Always,
    /// Workspace is stopped and requires manual start.
    #[serde(default)]
    Halted,
}

impl Default for RunStrategy {
    fn default() -> Self {
        Self::Halted
    }
}

#[serde(rename_all = "camelCase")]
pub struct WorkspaceClaimSpec {
    #[serde(default)]
    pub run_strategy: RunStrategy,
    // ... other fields
}

use std::fmt;

/// A validated workspace name conforming to RFC 1123 DNS label rules.
///
/// Workspace names must:
/// - Be non-empty
/// - Not exceed 63 characters
/// - Contain only lowercase alphanumeric characters and hyphens
/// - Not start or end with a hyphen
///
/// This newtype ensures these invariants hold for all values in scope.
#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd, Hash)]
pub struct WorkspaceName(String);

impl WorkspaceName {
    /// Construct a `WorkspaceName` from a string, validating RFC 1123 compliance.
    ///
    /// # Errors
    ///
    /// Returns a descriptive error message if the name fails validation.
    pub fn new(name: impl Into<String>) -> Result<Self, String> {
        let name = name.into();

        if name.is_empty() {
            return Err("workspace name cannot be empty".to_string());
        }

        if name.len() > 63 {
            return Err(format!(
                "workspace name exceeds 63 characters (got {})",
                name.len()
            ));
        }

        if name.starts_with('-') {
            return Err("workspace name cannot start with a hyphen".to_string());
        }

        if name.ends_with('-') {
            return Err("workspace name cannot end with a hyphen".to_string());
        }

        if !name
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
        {
            return Err(
                "workspace name must contain only lowercase letters, digits, and hyphens"
                    .to_string(),
            );
        }

        Ok(Self(name))
    }

    /// Return the inner string as a borrowed reference.
    #[inline]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Consume the newtype and return the inner string.
    #[inline]
    pub fn into_inner(self) -> String {
        self.0
    }
}

impl AsRef<str> for WorkspaceName {
    #[inline]
    fn as_ref(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for WorkspaceName {
    #[inline]
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::ops::Deref for WorkspaceName {
    type Target = str;

    #[inline]
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn valid_names() {
        assert!(WorkspaceName::new("my-workspace").is_ok());
        assert!(WorkspaceName::new("workspace123").is_ok());
        assert!(WorkspaceName::new("a").is_ok());
        assert!(WorkspaceName::new("my-workspace-123").is_ok());
        assert!(WorkspaceName::new("a1b2c3").is_ok());
    }

    #[test]
    fn empty_name() {
        let err = WorkspaceName::new("").expect_err("should reject empty");
        assert_eq!(err, "workspace name cannot be empty");
    }

    #[test]
    fn exceeds_max_length() {
        let long = "a".repeat(64);
        let err = WorkspaceName::new(long).expect_err("should reject > 63 chars");
        assert!(err.contains("exceeds 63 characters"));
    }

    #[test]
    fn starts_with_hyphen() {
        let err = WorkspaceName::new("-workspace").expect_err("should reject leading hyphen");
        assert_eq!(err, "workspace name cannot start with a hyphen");
    }

    #[test]
    fn ends_with_hyphen() {
        let err = WorkspaceName::new("workspace-").expect_err("should reject trailing hyphen");
        assert_eq!(err, "workspace name cannot end with a hyphen");
    }

    #[test]
    fn uppercase_rejected() {
        let err = WorkspaceName::new("MyWorkspace").expect_err("should reject uppercase");
        assert!(err.contains("lowercase letters"));
    }

    #[test]
    fn underscores_rejected() {
        let err = WorkspaceName::new("my_workspace").expect_err("should reject underscore");
        assert!(err.contains("lowercase letters"));
    }

    #[test]
    fn spaces_rejected() {
        let err = WorkspaceName::new("my workspace").expect_err("should reject space");
        assert!(err.contains("lowercase letters"));
    }

    #[test]
    fn as_ref_trait() {
        let name = WorkspaceName::new("test-ws").expect("valid name");
        let s: &str = name.as_ref();
        assert_eq!(s, "test-ws");
    }

    #[test]
    fn display_impl() {
        let name = WorkspaceName::new("prod-ws").expect("valid name");
        assert_eq!(name.to_string(), "prod-ws");
    }

    #[test]
    fn deref_coercion() {
        let name = WorkspaceName::new("my-ws").expect("valid name");
        // Deref coercion allows methods on `str`
        assert_eq!(name.len(), 5);
        assert!(name.contains("ws"));
    }

    #[test]
    fn clone_and_eq() {
        let name1 = WorkspaceName::new("test").expect("valid name");
        let name2 = name1.clone();
        assert_eq!(name1, name2);
    }

    #[test]
    fn into_inner() {
        let name = WorkspaceName::new("workspace").expect("valid name");
        let s = name.into_inner();
        assert_eq!(s, "workspace");
    }
}

//! Error type for the workspace-client library.
//!
//! Provides typed error handling for HTTP client operations against the
//! workstation-api, allowing callers to distinguish between transport,
//! deserialization, API, and validation failures.

use thiserror::Error;

/// Error type for workspace client operations.
///
/// Represents all failure modes when communicating with the workstation-api.
/// Each variant is typed to allow callers to handle specific error conditions.
#[derive(Debug, Error)]
pub enum WorkspaceClientError {
    /// HTTP transport error (connection, timeout, TLS, etc.).
    #[error("HTTP transport error: {0}")]
    Transport(#[from] reqwest::Error),

    /// API returned an error response with structured error details.
    #[error("API error: {status} {message}")]
    ApiError {
        /// HTTP status code returned by the API.
        status: u16,
        /// Error message from the API response body.
        message: String,
    },

    /// Response body JSON deserialization failed.
    #[error("failed to deserialize API response: {0}")]
    Deserialization(#[from] serde_json::Error),

    /// Workspace name validation failed (not a valid RFC 1123 DNS label).
    #[error("invalid workspace name: {reason}")]
    InvalidWorkspaceName {
        /// Human-readable reason for the validation failure.
        reason: String,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn display_transport_error() {
        let err = WorkspaceClientError::Transport(
            reqwest::Error::status(
                reqwest::Url::parse("http://example.com").expect("valid url"),
                reqwest::status::StatusCode::INTERNAL_SERVER_ERROR,
            ),
        );
        let msg = err.to_string();
        assert!(msg.contains("HTTP transport error"));
    }

    #[test]
    fn display_api_error() {
        let err = WorkspaceClientError::ApiError {
            status: 400,
            message: "workspace not found".to_string(),
        };
        assert_eq!(err.to_string(), "API error: 400 workspace not found");
    }

    #[test]
    fn display_deserialization_error() {
        let json_err = serde_json::from_str::<serde_json::Value>("invalid json")
            .expect_err("invalid json");
        let err = WorkspaceClientError::Deserialization(json_err);
        let msg = err.to_string();
        assert!(msg.contains("failed to deserialize API response"));
    }

    #[test]
    fn display_invalid_workspace_name() {
        let err = WorkspaceClientError::InvalidWorkspaceName {
            reason: "contains uppercase letters".to_string(),
        };
        assert_eq!(
            err.to_string(),
            "invalid workspace name: contains uppercase letters"
        );
    }

    #[test]
    fn from_reqwest_error() {
        let reqwest_err = reqwest::Error::status(
            reqwest::Url::parse("http://example.com").expect("valid url"),
            reqwest::status::StatusCode::UNAUTHORIZED,
        );
        let err: WorkspaceClientError = reqwest_err.into();
        assert!(matches!(err, WorkspaceClientError::Transport(_)));
    }

    #[test]
    fn from_serde_json_error() {
        let json_err = serde_json::from_str::<serde_json::Value>("not json")
            .expect_err("invalid json");
        let err: WorkspaceClientError = json_err.into();
        assert!(matches!(err, WorkspaceClientError::Deserialization(_)));
    }

    #[test]
    fn error_implements_display() {
        let err = WorkspaceClientError::InvalidWorkspaceName {
            reason: "starts with hyphen".to_string(),
        };
        // thiserror provides Display via #[error("...")] attributes
        let _display_string: String = err.to_string();
    }
}

# Rust development flake with container tooling and Kubernetes CLI
{
  description = "Rust development environment with container and k8s tools";

  inputs = {
    nixpkgs.url = "github:nixos/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
    rust-overlay.url = "github:oxalica/rust-overlay";
  };

  outputs = { self, nixpkgs, flake-utils, rust-overlay }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        overlays = [ (import rust-overlay) ];
        pkgs = import nixpkgs {
          inherit system overlays;
        };

        # Rust toolchain: stable with rustfmt and clippy
        rust-toolchain = pkgs.rust-bin.stable.latest.default.override {
          extensions = [ "rustfmt" "clippy" "rust-analyzer" ];
        };
      in
      {
        devShells.default = pkgs.mkShell {
          name = "rust-dev";
          buildInputs = with pkgs; [
            # Rust toolchain
            rust-toolchain
            cargo

            # Task runner
            just

            # Container tooling
            buildah
            skopeo

            # Kubernetes CLI tools
            kubectl
            fluxcd

            # Development utilities
            pkg-config
            openssl
          ];

          shellHook = ''
            echo "🦀 Rust development environment loaded"
            echo "Tools available:"
            echo "  - rustc, cargo, rustfmt, clippy"
            echo "  - just (task runner)"
            echo "  - buildah, skopeo (containers)"
            echo "  - kubectl, flux (Kubernetes)"
          '';
        };
      }
    );
}

